test('F5-D native HTTP CSRF MFA confirmation incident public and customer CSAT boundaries',function(): void{$f=dFixture();$t=bTicket($f);$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$auth=['cookies'=>[],'csrf'=>''];$client=['cookies'=>[],'csrf'=>''];try{same(401,bHttp($server,'/api/v1/admin/support-advanced/report?from=2026-01-01T00:00:00Z&to=2027-01-01T00:00:00Z&timezone=UTC',$auth)[0]);bLogin($server,$f['admin'],$auth);$before=dCounts($f);$sim=bHttp($server,'/api/v1/admin/support-advanced/simulate',$auth,['ticket_id'=>$t['id'],'spec'=>dSpec()]);same(200,$sim[0]);same('MATCH',$sim[1]['data']['result']);same($before,dCounts($f));$body=['action'=>'incident-new','payload'=>['department_id'=>$f['departments'][0],'version'=>0,'title'=>'Public synthetic','description'=>'Public','private_root'=>'PRIVATE_HTTP_ROOT','affected'=>'Synthetic']];same(403,bHttp($server,'/api/v1/admin/support-advanced/prepare',$auth,$body,csrf:false)[0]);$prep=bHttp($server,'/api/v1/admin/support-advanced/prepare',$auth,$body);same(200,$prep[0]);$body['confirmation']=['id'=>$prep[1]['data']['id'],'accepted'=>true];$key=Id::uuid();$exec=bHttp($server,'/api/v1/admin/support-advanced/execute',$auth,$body,$key);same(200,$exec[0]);same($exec[1]['data'],bHttp($server,'/api/v1/admin/support-advanced/execute',$auth,$body,$key)[1]['data']);$i=$exec[1]['data'];dCommand($f,'incident-link',['ticket_id'=>$t['id'],'version'=>1,'incident_id'=>$i['id']]);dClientLogin($server,$f['client'],$client);$view=bHttp($server,'/api/v1/client/support-advanced/incident?id='.$i['id'].'&ticket_id='.$t['id'],$client);same(200,$view[0]);same(false,str_contains($view[2],'PRIVATE_HTTP_ROOT'));same(404,bHttp($server,'/api/v1/client/support-advanced/report',$client)[0]);same(403,bHttp($server,'/api/v1/client/support-advanced/csat',$client,['ticket_id'=>$t['id'],'ticket_version'=>2,'version'=>0,'score'=>5,'comment'=>'Synthetic'],csrf:false)[0]);}finally{$server->stop();}});
test('F5-D additive 052 to 053 upgrade preserves checksums and replay',function(): void{$root=dirname(__DIR__);$db=isolatedDomainDb();$dir=$root.'/storage/f5-d-prefix-'.bin2hex(random_bytes(4));mkdir($dir,0700);$files=[];try{foreach(glob($root.'/migrations/*.php') as $p){if(basename($p)<'053'){$to=$dir.'/'.basename($p);copy($p,$to);$files[]=$to;}}same(52,count((new \Hostider\Core\Database\Migrator($db,$dir))->migrate()));$old=$db->execute('SELECT version,checksum,status FROM schema_migrations ORDER BY version')->fetchAll();$m=new \Hostider\Core\Database\Migrator($db,$root.'/migrations');same(['053_support_automation_incident_csat.php','054_support_ui_state.php','055_support_auto_close.php','056_support_ticket_merge.php'],$m->migrate());same([],$m->migrate());same($old,$db->execute("SELECT version,checksum,status FROM schema_migrations WHERE version<'053' ORDER BY version")->fetchAll());$m->assertReady();}finally{foreach($files as $p){unlink($p);}rmdir($dir);}});
test('SUP-008 real A to B to A priority cycle is stopped by immutable repeated rule detection',function(): void{$f=dFixture();$t=bTicket($f);dRule($f,$t,dSpec('state_changed',[['kind'=>'priority','value'=>'NORMAL']],['field'=>'priority','op'=>'eq','value'=>'HIGH'],0));dRule($f,$t,dSpec('state_changed',[['kind'=>'priority','value'=>'HIGH']],['field'=>'priority','op'=>'eq','value'=>'NORMAL'],1));bState($f,$t,'WAITING_STAFF');dStage($f,$t,'STATE');dDrain($f);same(2,(int)$f['db']->execute("SELECT COUNT(*) FROM support_rule_executions WHERE result='APPLIED'")->fetchColumn());same(true,(int)$f['db']->execute("SELECT COUNT(*) FROM support_rule_executions WHERE result='LOOP_BLOCKED'")->fetchColumn()>0);same(2,(int)$f['db']->execute('SELECT MAX(depth) FROM support_automation_events')->fetchColumn());same('NORMAL',bRow($f,$t)['effective_priority']);});
test('SUP-008 four distinct rule chain reaches depth four and blocks the next action',function(): void{$f=dFixture();$t=bTicket($f,'LOW');$steps=[['CRITICAL','LOW'],['HIGH','CRITICAL'],['NORMAL','HIGH'],['LOW','NORMAL']];foreach($steps as $order=>[$from,$to]){dRule($f,$t,dSpec('state_changed',[['kind'=>'priority','value'=>$to]],['field'=>'priority','op'=>'eq','value'=>$from],$order));}bState($f,$t,'WAITING_STAFF');dStage($f,$t,'STATE');dDrain($f);same(4,(int)$f['db']->execute('SELECT MAX(depth) FROM support_automation_events')->fetchColumn());same(4,(int)$f['db']->execute("SELECT COUNT(*) FROM support_rule_executions WHERE result='APPLIED'")->fetchColumn());same('LOW',bRow($f,$t)['effective_priority']);same(true,(int)$f['db']->execute("SELECT COUNT(*) FROM support_rule_executions WHERE result='LOOP_BLOCKED'")->fetchColumn()>0);});
test('SUP-008 native source adapter seed selects matching triggers without old-event starvation',function(): void{$f=dFixture();$t=bTicket($f);dRule($f,$t,dSpec('staff_replied'));bReply($f,$t);$r=$f['automation']->seed();same(1,$r['staged']);dDrain($f);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_tags')->fetchColumn());same('staff_replied',$f['db']->execute('SELECT trigger_name FROM support_automation_events')->fetchColumn());same(0,$f['automation']->seed()['staged']);same('sla_risk',\Hostider\Support\Automation\Engine::trigger('WORK','SLA_BREACH'));same(null,\Hostider\Support\Automation\Engine::trigger('SUPPORT','INTERNAL_NOTE'));});
test('SUP-008 automation assignment uses canonical native eligibility and then assigned adapter',function(): void{$f=dFixture(true);bRoster($f,$f['admin']['user']);$t=bTicket($f);dRule($f,$t,dSpec(actions:[['kind'=>'assign','value'=>$f['admin']['user']]]));dRule($f,$t,dSpec('assigned',[['kind'=>'tag','value'=>'assigned']]));dStage($f,$t);dDrain($f);same($f['admin']['user'],bWork($f,$t)['assignee_id']);same(['assigned'],array_column($f['db']->execute('SELECT tag FROM support_ticket_tags')->fetchAll(),'tag'));same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='ASSIGNED'")->fetchColumn());});
test('SUP-008 rule incident link and public update adapter preserve customer isolation and SLA',function(): void{$f=dFixture(true);$t=bTicket($f);$i=dIncident($f);dRule($f,$t,dSpec(actions:[['kind'=>'incident','value'=>$i['id']]]));dStage($f,$t);dDrain($f);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_incident_tickets')->fetchColumn());dRule($f,$t,dSpec('incident_updated',[['kind'=>'tag','value'=>'incident-updated']]));$clocks=bClocks($f,$t);dCommand($f,'incident-update',['id'=>$i['id'],'version'=>1,'status'=>'IDENTIFIED','public_update'=>'Synthetic public update','private_root'=>'Synthetic private']);same(1,$f['automation']->seed()['staged']);dDrain($f);same($clocks,bClocks($f,$t));same('NEW',bRow($f,$t)['status']);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());});
test('SUP-008 two rules under concurrent event workers retain both canonical effects without finance or provider writes',function(): void{$f=dFixture();$t=bTicket($f);dRule($f,$t,dSpec(actions:[['kind'=>'tag','value'=>'one']],order:1));dRule($f,$t,dSpec(actions:[['kind'=>'tag','value'=>'two']],order:2));$p=dStage($f,$t);dPublish($f);$counts=[];foreach(['finance_journals','finance_payments','finance_wallet_entries','svc_services','svc_operations','cloud_operations'] as $table){$counts[$table]=(int)$f['db']->execute('SELECT COUNT(*) FROM '.$table)->fetchColumn();}foreach(dRace($f,$p,4) as $r){same(false,($r['result']??'')==='ERROR');}dDrain($f);same(2,(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_tags')->fetchColumn());same(3,(int)bRow($f,$t)['version']);foreach($counts as $table=>$count){same($count,(int)$f['db']->execute('SELECT COUNT(*) FROM '.$table)->fetchColumn());}});
test('SUP-008 expired native step up or revoked sponsor session cannot be bypassed by rule publication',function(): void{$f=dFixture();$t=bTicket($f);dRule($f,$t,dSpec());$p=dStage($f,$t);$f['db']->execute('UPDATE identity_sessions SET verified_at=TIMESTAMPADD(SECOND,-301,UTC_TIMESTAMP(6)) WHERE native_reference=?',[$f['admin']['reference']]);dPublish($f);$f['automation']->consume($p);same('SKIPPED',$f['db']->execute('SELECT result FROM support_rule_executions')->fetchColumn());same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_ticket_tags')->fetchColumn());same(403,raises(HttpError::class,fn()=>dRule($f,$t,dSpec()))->status);});
test('F5-D stale confirmation and rule publication rollback leave no half revision or idempotent success',function(): void{$f=dFixture();$t=bTicket($f);$cmd=new Commands($f['advanced']);$p=['id'=>Id::uuid(),'version'=>0,'department_id'=>$f['departments'][0],'customer_id'=>$f['client']['customer'],'sample_ticket_id'=>$t['id'],'spec'=>dSpec()];$body=['action'=>'rule-publish','payload'=>$p];$a=$cmd->command($f['admin']['reference'],'prepare',$body,Id::uuid(),Id::uuid());$body['confirmation']=['id'=>$a['id'],'accepted'=>true];bReply($f,$t);same(409,raises(HttpError::class,fn()=>$cmd->command($f['admin']['reference'],'execute',$body,Id::uuid(),Id::uuid()))->status);$a=$cmd->command($f['admin']['reference'],'prepare',['action'=>'rule-publish','payload'=>$p],Id::uuid(),Id::uuid());$body['confirmation']=['id'=>$a['id'],'accepted'=>true];$before=dCounts($f);$f['db']->execute("CREATE TRIGGER d_rule_failure BEFORE INSERT ON support_rule_revisions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic revision failure'");try{raises(PDOException::class,fn()=>$cmd->command($f['admin']['reference'],'execute',$body,Id::uuid(),Id::uuid()));same($before,dCounts($f));}finally{$f['db']->execute('DROP TRIGGER d_rule_failure');}});
test('F5-D native HTTP resolved customer CSAT submission replay and membership revocation are enforced',function(): void{$f=dFixture();$t=bTicket($f);dCommand($f,'csat-policy',['department_id'=>$f['departments'][0],'version'=>0,'window_seconds'=>3600]);bState($f,$t,'RESOLVED');$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$auth=['cookies'=>[],'csrf'=>''];try{dClientLogin($server,$f['client'],$auth);$p=['ticket_id'=>$t['id'],'ticket_version'=>2,'version'=>0,'score'=>5,'comment'=>'<script>synthetic()</script>'];$key=Id::uuid();$one=bHttp($server,'/api/v1/client/support-advanced/csat',$auth,$p,$key);same(200,$one[0]);same($one[1]['data'],bHttp($server,'/api/v1/client/support-advanced/csat',$auth,$p,$key)[1]['data']);$view=bHttp($server,'/api/v1/client/support-advanced/csat?ticket_id='.$t['id'],$auth);same(200,$view[0]);same('PLAIN_TEXT',$view[1]['data']['content_format']);same($p['comment'],$view[1]['data']['comment']);$f['db']->execute('DELETE FROM identity_memberships WHERE user_id=? AND customer_id=?',[$f['client']['user'],$f['client']['customer']]);same(true,in_array(bHttp($server,'/api/v1/client/support-advanced/csat',$auth,$p,$key)[0],[403,404],true));}finally{$server->stop();}});
test('F5-D live mail flag and non-test environments deny advanced automation before mutation',function(): void{$f=dFixture();foreach([['production',true],['staging',false],['production',false]] as [$env,$mail]){$c=$f['config'];$cfg=new \Hostider\Core\Config($env,$c->url,$c->key,$c->dsn,$c->dbUser,$c->dbPassword,mail:$mail);$m=new \Hostider\Support\Advanced\Common(new \Hostider\Commerce\Services($f['db'],$cfg));same(503,raises(HttpError::class,fn()=>$m->gate())->status);}same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_rule_heads')->fetchColumn());});
test('SUP-009 immutable encrypted root revisions never enter public projection and incident rules cannot resolve tickets',function(): void{$f=dFixture();$t=bTicket($f);$i=dIncident($f);dCommand($f,'incident-link',['ticket_id'=>$t['id'],'version'=>1,'incident_id'=>$i['id']]);dCommand($f,'incident-update',['id'=>$i['id'],'version'=>1,'status'=>'IDENTIFIED','public_update'=>'Explicit public status','private_root'=>'SECOND_PRIVATE_ROOT']);$rows=$f['db']->execute('SELECT id,private_encrypted FROM support_incident_updates WHERE incident_id=? ORDER BY version',[$i['id']])->fetchAll();same(2,count($rows));same('PRIVATE_ROOT_SECRET',$f['advanced']->crypto->decrypt($rows[0]['private_encrypted'],'incident-update-root:'.$rows[0]['id']));same('SECOND_PRIVATE_ROOT',$f['advanced']->crypto->decrypt($rows[1]['private_encrypted'],'incident-update-root:'.$rows[1]['id']));raises(PDOException::class,fn()=>$f['db']->execute('UPDATE support_incident_updates SET private_encrypted=private_encrypted'));same(422,raises(HttpError::class,fn()=>Ast::rule(dSpec('incident_updated',[['kind'=>'state','value'=>'RESOLVED']])))->status);$r=(new Incidents($f['advanced']))->view($f['client']['reference'],'client',['id'=>$i['id'],'ticket_id'=>$t['id']]);same(false,str_contains(json_encode($r),'PRIVATE'));same('NEW',bRow($f,$t)['status']);});
test('SUP-008 native staff HELD receipt binds its own immutable execution and never means delivery',function(): void{$f=dFixture();$t=bTicket($f);dRule($f,$t,dSpec(actions:[['kind'=>'notify','value'=>'HELD']]));dStage($f,$t);dDrain($f);$n=$f['db']->execute('SELECT * FROM support_staff_held')->fetch();$p=['event_uuid'=>$n['id'],'ticket_id'=>$t['id'],'execution_id'=>$n['execution_id']];$bad=$p;$bad['execution_id']=Id::uuid();raises(HttpError::class,fn()=>$f['automation']->held($bad));same('SUCCEEDED',$f['automation']->held($p));$before=dCounts($f);same('SUCCEEDED',$f['automation']->held($p));same($before,dCounts($f));same('HELD',$f['db']->execute('SELECT status FROM support_staff_held')->fetchColumn());same(0,(int)$f['db']->execute('SELECT COUNT(*) FROM support_mail_transport')->fetchColumn());});
test('SUP-008 native rules and execution views redact templates and enforce current department access',function(): void{$f=dFixture();$t=bTicket($f);dRule($f,$t,dSpec(actions:[['kind'=>'note','value'=>'PRIVATE_TEMPLATE_TEXT']]));dStage($f,$t);dDrain($f);$views=new \Hostider\Support\Advanced\Views($f['advanced']);$r=$views->view($f['admin']['reference'],'rules',['department_id'=>$f['departments'][0],'customer_id'=>$f['client']['customer']]);same(1,count($r['rules']));same(false,str_contains(json_encode($r),'PRIVATE_TEMPLATE_TEXT'));$r=$views->view($f['admin']['reference'],'executions',['ticket_id'=>$t['id']]);same(1,count($r['executions']));same('SYSTEM_RULE',$r['executions'][0]['actor_kind']);$detail=$f['service']->view($f['admin']['reference'],'admin','detail',['id'=>$t['id']]);$notes=array_values(array_filter($detail['messages'],fn($n)=>$n['type']==='internal_note'));same('SYSTEM_RULE',$notes[0]['system_origin']['actor_kind']);$f['db']->execute('DELETE FROM support_department_members WHERE department_id=? AND user_id=?',[$f['departments'][0],$f['admin']['user']]);same(404,raises(HttpError::class,fn()=>$views->view($f['admin']['reference'],'executions',['ticket_id'=>$t['id']]))->status);});
test('F5-D native HTTP CSAT comment may be omitted and normalizes to empty on replay',function(): void{$f=dFixture();$t=bTicket($f);dCommand($f,'csat-policy',['department_id'=>$f['departments'][0],'version'=>0,'window_seconds'=>3600]);bState($f,$t,'RESOLVED');$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$auth=['cookies'=>[],'csrf'=>''];try{dClientLogin($server,$f['client'],$auth);$p=['ticket_id'=>$t['id'],'ticket_version'=>2,'version'=>0,'score'=>3];$key=Id::uuid();$one=bHttp($server,'/api/v1/client/support-advanced/csat',$auth,$p,$key);same(200,$one[0]);$p['comment']='';same($one[1]['data'],bHttp($server,'/api/v1/client/support-advanced/csat',$auth,$p,$key)[1]['data']);$r=bHttp($server,'/api/v1/client/support-advanced/csat?ticket_id='.$t['id'],$auth);same(200,$r[0]);same('',$r[1]['data']['comment']);same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_rating_revisions')->fetchColumn());}finally{$server->stop();}});
